    'asterisk_settings.rtp_help_body' => 'Styrer, hvilket portinterval der fører lyd (RTP), og om Asterisk afviser lyd fra en uventet kilde. Denne fil (<code>/etc/asterisk/rtp.conf</code>) genereres nu af panelet; manuelle ændringer på serveren går tabt ved næste "Anvend".',
    'asterisk_settings.field_rtp_start' => 'RTP-startport',
    'asterisk_settings.rtp_start_help' => 'Start på det portinterval, der er reserveret til lydstrømme. Hvert samtidigt opkald bruger porte fra dette interval.',
    'asterisk_settings.field_rtp_end' => 'RTP-slutport',
    'asterisk_settings.rtp_end_help' => 'Slut på intervallet. coturn (TURN-relay) bruger 13479-14999 – et overlap ødelægger WebRTC-lyd og afvises ved gem.',
    'asterisk_settings.field_rtp_strict' => 'Streng RTP (strictrtp)',
