    'asterisk_settings.rtp_restart_warning' => 'Indstillingen Streng RTP træder i kraft med "Anvend". En ændring af PORTINTERVALLET kræver dog en fuld genstart af Asterisk – portpuljen tildeles én gang, når modulet indlæses.',
    'asterisk_settings.udptl_section_title' => 'T.38 UDPTL-indstillinger (faxmedier)',
    'asterisk_settings.udptl_help_body' => 'Definerer UDP-portintervaller og parametre for fremadrettet fejlkorrektion (FEC / checksum) for T.38-faxpakker (UDPTL). Denne fil (<code>/etc/asterisk/udptl.conf</code>) administreres dynamisk.',
