    'trunks.connection_mode_help' => 'IP-baseret: modparten identificeres ud fra sin IP-adresse, og dens kontakt holdes statisk – den anbefalede tilstand for en modpart med fast IP på samme netværk. Indgående registrering: modparten sender os en SIP REGISTER, og dens adresse læres fra den registrering. Denne tilstand kræver et brugernavn og en adgangskode; modparten godkender både sin registrering og sine opkald med dem.',
