    'sound_packs.title' => 'Officielle Asterisk-lydpakker',
    'sound_packs.help_title' => 'Asterisk-lydpakker',
    'sound_packs.help_body' => 'Downloader og installerer Asterisks officielle systembeskeder og ventemusik fra <code>downloads.asterisk.org</code>. Hver pakke er ét sprog i ét format; Asterisk afspiller det format, der matcher opkaldets codec, og transkoder ellers (g722 til G.722, ulaw/alaw til operatører).<br>- <strong>Core:</strong> systembeskeder, cifre, voicemail. <strong>Extra:</strong> yderligere beskeder; samme sprogs core-pakke skal installeres først.<br>- <strong>Ventemusik (opsound):</strong> installeres i <code>/var/lib/asterisk/moh/opsound</code>; for at afspille den skal du oprette en MOH-klasse med navnet <strong>opsound</strong> på fanen Ventemusik.<br>- <strong>Türkçe (AiPBX):</strong> AiPBX\' egne tyrkiske beskeder (GitHub-release, SHA256-verificeret); standardsproget er tyrkisk, så hvis de fjernes, bliver systembeskederne tavse. Fjernelse sletter kun de filer, pakken installerede.',
