    'certificates.help_title' => 'Certifikatvejledning',
    'certificates.help_body' => 'Portalen (HTTPS), WebRTC TURNS og SIP-TLS/WSS deler ét certifikat; ændringer her anvendes på Apache, coturn og Asterisk samtidig. <b>Let\'s Encrypt</b> er gratis og fornyer sig selv; domænet skal pege på denne server, og port 80 skal kunne nås fra internettet. Hvis din organisation har et certifikat, kan du <b>uploade det</b> (PEM eller PFX); uploadede certifikater fornyes ikke automatisk, så upload et nyt, før det udløber. Med et <b>selvsigneret</b> certifikat viser browsere en advarsel, og TURNS virker ikke i browsere: WebRTC-opkald bag firewalls kan mangle lyd.',
