    'queue_reports.title' => 'Kørapportcenter',
    'queue_reports.help_title' => 'Vejledning til kørapporter',
    'queue_reports.help_body' => 'Hvert opkald, der kommer ind i en kø, tælles én gang. <b>Besvaret</b>: forbundet til en agent. <b>Tabt</b>: opkalderen lagde på under ventetiden, eller køen fik timeout. <b>Kort afbrudt</b>: lagt på inden for %d sekunder; tælles ikke med i serviceniveauet. <b>Serviceniveau</b>: opkald besvaret inden for målet i forhold til alle opkald undtagen kort afbrudte. <b>ASA</b>: gennemsnitlig ventetid for besvarede opkald. <b>AHT</b>: gennemsnitlig samtaletid. <b>Svarrate</b> (agent): hvor ofte agenten svarede, når køen ringede til vedkommende. <b>Tilbagekald</b>: et tabt opkald regnes som løst, når nummeret senere blev ringet op fra et lokalnummer, eller ringede igen og blev besvaret. Data kommer fra Asterisks kølog; rapporten kan downloades som PDF eller Excel.',
