    'ai_tts.help_body' => 'Omdanner tekst til naturlig tale med cloudtjenester (Google, Amazon Polly, Azure, ElevenLabs, OpenAI). Lyt til resultatet, download det som MP3, eller gem det som en <b>meddelelse</b> med ét klik: det konverteres til Asterisks format (8 kHz WAV) og føjes til Lyde &amp; meddelelser til brug i IVR\'er, indgående ruter og tidsbetingelser (træder i kraft efter Anvend). <b>Disse tjenester er betalingstjenester</b> og afregner pr. tegn; hver syntese gemmes i historikken med antal tegn. Adgangsnøgler hentes fra hver udbyders konsol, gemmes krypteret og vises aldrig igen på siden.',
