    'push.help_intro' => 'AI PBX-mobilsoftphonen har en <strong>lagdelt notifikationsarkitektur</strong>:',
    'push.help_layer0' => '<strong>Lag 0 (ingen afhængighed - standard):</strong> en vedvarende WSS-forbindelse, en Android 15-kompatibel <code>specialUse</code>-forgrundstjeneste og en Doze-resistent <code>AlarmManager</code>-watchdog, der genstarter den. Der kræves ingen ekstern tjeneste; opkald kommer igennem, selv når enheden er inaktiv, eller skærmen er slukket.',
