    'mailtpl.invite_new.subject' => '[{brand}] Din konto er oprettet - angiv din adgangskode',
    'mailtpl.invite_new.body' => '<p>Hej {name}</p><p>Din konto på omstillingen <strong>{brand}</strong> er klar. Angiv din adgangskode med knappen nedenfor for at logge ind.</p>{account_details}{reset_button}<p>Hvis knappen ikke virker, så åbn dette link: {reset_link}</p>{mobile_section}<p><em>Linket til adgangskoden er gyldigt i 48 timer og virker én gang. Hvis du ikke forventede denne e-mail, så kontakt din systemadministrator.</em></p>',
    'mailtpl.invite.subject' => '[{brand}] Dit link til login og adgangskode',
    'mailtpl.invite.body' => '<p>Hej {name}</p><p>Her er et nyt link til at angive din adgangskode til <strong>{brand}</strong>.</p>{account_details}{reset_button}<p>Hvis knappen ikke virker, så åbn dette link: {reset_link}</p>{mobile_section}<p><em>Linket til adgangskoden er gyldigt i 48 timer og virker én gang. Hvis du ikke har bedt om det, så kontakt din systemadministrator.</em></p>',
    'mailtpl.password_reset.subject' => '[{brand}] Nulstil din adgangskode',
    'mailtpl.password_reset.body' => '<p>Hej {name}</p><p>Der er anmodet om nulstilling af adgangskoden til din konto <strong>{username}</strong>.</p>{reset_button}<p>Hvis knappen ikke virker, så åbn dette link: {reset_link}</p><p><em>Linket er gyldigt i 30 minutter. Hvis du ikke har bedt om det, kan du se bort fra denne e-mail; din adgangskode forbliver den samme.</em></p>',
    'mailtpl.voicemail.subject' => 'Ny voicemail fra {caller} ({duration})',
    'mailtpl.voicemail.body' => '<p>Hej {name}</p><p>Du har en ny besked i voicemailboksen <strong>{mailbox}</strong>.</p><ul><li><strong>Fra:</strong> {caller}</li><li><strong>Modtaget:</strong> {date}</li><li><strong>Længde:</strong> {duration}</li></ul><p>Hvis optagelsen er vedhæftet, kan du afspille den direkte her. Du kan også lytte til den i portalen ({portal_link}) eller ved at ringe *97.</p>',
    'mailtpl.fax_received.subject' => 'Ny fax modtaget - {department} ({did})',
    'mailtpl.fax_received.body' => '<p>Der er modtaget en ny fax.</p><ul><li><strong>Enhed:</strong> {department}</li><li><strong>Faxnummer:</strong> {did}</li><li><strong>Fra:</strong> {caller}</li><li><strong>Sider:</strong> {pages}</li><li><strong>Modtaget:</strong> {date}</li></ul><p>Faxen vedhæftes som PDF, når det er slået til. Alle faxer ligger i faxindbakken: {portal_link}</p>',
